import { defineConfig } from 'astro/config';
import react from '@astrojs/react';

export default defineConfig({
  output: 'static',
  trailingSlash: 'always',
  devToolbar: { enabled: false },
  integrations: [react()],
  // Article HTML is generated by src/lib/markdown.ts. Avoid a second, unused
  // syntax-highlighting pass inside Astro's content loader.
  markdown: { syntaxHighlight: false },
  vite: {
    build: {
      rolldownOptions: {
        output: {
          codeSplitting: {
            groups: [{
              name: 'town-webgl-shaders',
              // Keep the original GLSL intact, but deliver its shared include
              // graph together instead of dozens of tiny startup requests.
              test: (id) => /\/@babylonjs\/core\/Shaders\/(?:ShadersInclude\/|(?:pbr|shadowMap|depthBoxBlur|color|postprocess|rgbdDecode|ssao2|ssaoCombine|pass)\.(?:vertex|fragment)\.js$)/.test(id.replaceAll('\\', '/')),
            }],
          },
        },
      },
    },
    plugins: [{
      name: 'astro-routes-hmr-compat',
      enforce: 'post',
      transform(code, id) {
        if (!id.includes('virtual:astro:routes')) return null;
        // Astro 7.2.4 emits this virtual module with `astro/app` during a
        // content HMR rebuild. That barrel can be invalidated to an export
        // without deserializeRouteInfo; the stable manifest entrypoint keeps
        // route refreshes working without touching node_modules.
        return code.replace(
          "import { deserializeRouteInfo } from 'astro/app';",
          "import { deserializeRouteInfo } from 'astro/app/manifest';",
        );
      },
    }],
  },
});
